/// <summary>
/// Data contract class for <c>METAutoPostInvJournalService</c> service.
/// </summary>
/// <remarks>
/// This is the Data Contract class for the <c>METAutoPostInvJournalService</c> service.
/// </remarks>
[DataContractAttribute]
public class METAutoPostInvJournalContract
{
    List        journalIdList = new List(Types::Class);
    DataAreaId  dataArea;
    boolean     transferError;

}

Method.Source:
/// <summary>
/// gets list of journal id's
/// </summary>
/// <param name = "_journalIdList">list of journal id's</param>
/// <returns>list of journal id's</returns>
[DataMemberAttribute("@MET:JournalList"),
    AifCollectionTypeAttribute("@MET:JournalList", Types::Class, classStr(METAutoPostInvJournalRequestContract)),
    AifCollectionTypeAttribute("return", Types::Class, classStr(METAutoPostInvJournalRequestContract))]
public List getJournalList(List _journalIdList = journalIdList)
{
    journalIdList = _journalIdList;
    return journalIdList;
}

/// <summary>
/// parameter to specify the company in which the journals should post.
/// </summary>
/// <param name = "_dataArea">
/// string value.
/// </param>
/// <returns>
/// Returns the company in which the journals should post.
/// </returns>
[
    DataMemberAttribute("@SYS181879"),
    SysOperationLabelAttribute(literalstr("@SYS181879")),
    SysOperationDisplayOrderAttribute('3')
]
public DataAreaId parmDataArea(DataAreaId _dataArea = dataArea)
{
    dataArea = _dataArea;
    return dataArea;
}

/// <summary>
/// parameter for transferring errors to a new journal.
/// </summary>
/// <param name = "_transferError">
/// boolean value.
/// </param>
/// <returns>
/// Returns True if the errors have to be traansferred to a new journal/else false.
/// </returns>
[
    DataMemberAttribute('@MET:TransferErrors'),
    SysOperationLabelAttribute(literalstr("@MET:TransferErrors")),
    SysOperationDisplayOrderAttribute('3')
]
public boolean parmTransferError(boolean _transferError = transferError)
{
    transferError = _transferError;
    return transferError;
}
